    import time

    LANGUAGE_WRAPPER = 'Determine the number of ordered pairs (x, y) of positive integers satisfying both x ≤ {a_factor}·y ≤ {upper1} and y ≤ {b_factor}·x ≤ {upper2}, with gcd(x, y) = {gcd_target}. Provide the exact count.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate parameters a, b, g, and upper bounds so that after scaling
# the effective maxima X = floor((upper2/g)/b) and Y = floor((upper1/g)/a)
# are moderate (for performance) but large enough to ensure nontrivial counting.
# We also guarantee there are points in the wedge region.

def count_F(L, M, A, B):
    if L <= 0 or M <= 0:
        return 0
    total = 0
    for v in range(1, M + 1):
        lb = (v + B - 1) // B  # ceil(v/B)
        ub = A * v
        if ub > L:
            ub = L
        if ub >= lb:
            total += (ub - lb + 1)
    return total

for _ in range(1000):
    a = rng.randint(2, 6)
    b = rng.randint(2, 6)
    g = rng.randint(1, 8)

    # Choose target X and Y (post-scaling maxima) in a nontrivial range
    X = rng.randint(1500, 30000)
    Y = rng.randint(1500, 30000)

    # Construct upper1 and upper2 via the chain ceilings so that
    # floor((upper1/g)/a) = Y and floor((upper2/g)/b) = X
    U1_prime = a * Y + rng.randint(0, a - 1)
    U2_prime = b * X + rng.randint(0, b - 1)
    upper1 = g * U1_prime + rng.randint(0, g - 1)
    upper2 = g * U2_prime + rng.randint(0, g - 1)

    # Quick feasibility check: wedge has some mass without gcd restriction
    # Using F(L, M, a, b) with L=X and M=Y
    pairs_all = count_F(X, Y, a, b)
    if pairs_all < 5000:
        # Too trivial, try again
        continue

    # Additional mild diversity constraints
    if a == b and rng.random() < 0.5:
        continue

    return {
        'a_factor': a,
        'b_factor': b,
        'upper1': upper1,
        'upper2': upper2,
        'gcd_target': g
    }

# Fallback (deterministic but still nontrivial) if random attempts failed
a, b, g = 3, 5, 2
X, Y = 5000, 7000
U1_prime = a * Y
U2_prime = b * X
upper1 = g * U1_prime
upper2 = g * U2_prime
return {
    'a_factor': a,
    'b_factor': b,
    'upper1': upper1,
    'upper2': upper2,
    'gcd_target': g
