    def verifier(assign):
# Recompute, validate domain constraints, and return (True, answer).
# When invalid, return (False, None).
try:
    a = int(assign.get('a_factor', 0))
    b = int(assign.get('b_factor', 0))
    U1 = int(assign.get('upper1', 0))
    U2 = int(assign.get('upper2', 0))
    g = int(assign.get('gcd_target', 0))
except Exception:
    # Non-integer values
    return (False, None)  # invalid due to type issues

# Basic validity checks
if not (isinstance(a, int) and isinstance(b, int) and isinstance(U1, int) and isinstance(U2, int) and isinstance(g, int)):
    return (False, None)  # invalid types
if a < 2 or b < 2 or g < 1 or U1 < 1 or U2 < 1:
    return (False, None)  # invalid parameter ranges

# Reduce by gcd_target: set x = g*x', y = g*y'
U1p = U1 // g
U2p = U2 // g
if U1p <= 0 or U2p <= 0:
    # No feasible pairs
    return (True, 0)

# Effective rectangle bounds after chain inequalities
# x' ≤ floor(U2'/b), y' ≤ floor(U1'/a)
X = U2p // b
Y = U1p // a

# Enforce nontriviality to discourage trivial counting
if X < 1000 or Y < 1000:
    # Too small; fails difficulty policy
    return (False, None)

# Helper: count pairs (u, v) with 1 ≤ u ≤ L, 1 ≤ v ≤ M, v ≤ b*u and u ≤ a*v
def count_F(L, M, A, B):
    if L <= 0 or M <= 0:
        return 0
    total = 0
    # Sum over v (i.e., y')
    for v in range(1, M + 1):
        lb = (v + B - 1) // B  # ceil(v/B)
        ub = A * v
        if ub > L:
            ub = L
        if ub >= lb:
            total += (ub - lb + 1)
    return total

# Möbius function up to T = min(X, Y)
T = X if X < Y else Y
if T <= 0:
    return (True, 0)

# Linear sieve for Möbius mu[1..T]
mu = [0] * (T + 1)
mu[1] = 1
is_comp = [False] * (T + 1)
primes = []
for i in range(2, T + 1):
    if not is_comp[i]:
        primes.append(i)
        mu[i] = -1
    for p in primes:
        ip = i * p
        if ip > T:
            break
        is_comp[ip] = True
        if i % p == 0:
            mu[ip] = 0
            break
        else:
            mu[ip] = -mu[i]

# Inclusion-Exclusion (Möbius inversion) over d dividing both x' and y'
# Count of primitive pairs = sum_{d=1..T} mu[d] * F( floor(X/d), floor(Y/d), a, b )
ans = 0
for d in range(1, T + 1):
    if mu[d] == 0:
        continue
    Ld = X // d
    Md = Y // d
    if Ld <= 0 or Md <= 0:
        break
    ans += mu[d] * count_F(Ld, Md, a, b)

# Non-negativity sanity check
if ans < 0:
    # Numerical sanity: count cannot be negative
    return (False, None)

# Answer is the number of (x, y) with gcd(x, y) = g satisfying the inequalities
return (True, ans)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

